"use client";

import { FormEvent, isValidElement, useCallback, useEffect, useMemo, useState } from "react";

type Row = Record<string, unknown>;
type Overview = { banks: Row[]; receivables: { items: Row[]; totals: Row }; payables: { items: Row[]; totals: Row }; statements: { profitAndLoss: Row; balanceSheet: Row }; cash: { totals: Row }; recentVouchers: Row[]; expenseCategories: Row[]; revenueCategories: Row[]; costCenters: Row[]; parties: Row[]; accounts: Row[]; periods: Row[]; journals: Row[]; transfers: Row[]; reconciliations: Row[]; vatReturns: Row[]; creditDebitNotes: Row[]; adjustments: Row[]; salesInvoices: Row[]; purchaseInvoices: Row[]; fiscalYears: Row[]; departments: Row[]; currencies: Row[]; exchangeRates: Row[]; budgets: Row[]; fxRevaluations: Row[]; ledgerExpenses: Row[]; ledgerRevenues: Row[] };
const money = (value: unknown) => `${Number(value ?? 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ر.س`;
const date = (value: unknown) => value ? new Date(String(value)).toLocaleDateString("en-US") : "—";
const input = "w-full rounded-lg border border-slate-300 bg-white px-3 py-2";
async function uploadAttachment(entityType:string,entityId:unknown,file:File|null) { if(!file)return; const body=new FormData();body.set("entityType",entityType);body.set("entityId",String(entityId));body.set("file",file);const response=await fetch("/api/attachments",{method:"POST",body});const json=await response.json();if(!response.ok)throw new Error(json.error); }

export default function AccountingClient({ initialTab }: { initialTab?: string }) {
  const normalizedTab = initialTab === "vat" ? "vatReturns" : initialTab === "receipt" || initialTab === "payment" ? "vouchers" : initialTab;
  const [data, setData] = useState<Overview | null>(null), [tab, setTab] = useState(normalizedTab || "overview"), [busy, setBusy] = useState(false), [message, setMessage] = useState("");
  const [report, setReport] = useState<Row | Row[] | null>(null), [reportName, setReportName] = useState("trial-balance");
  const [reportFrom,setReportFrom]=useState(""),[reportTo,setReportTo]=useState(""),[reportAccountId,setReportAccountId]=useState("");
  const [reportBudgetId,setReportBudgetId]=useState("");
  const load = useCallback(async () => { const response = await fetch("/api/finance", { cache: "no-store" }); const json = await response.json(); if (!response.ok) throw new Error(json.error); setData(json); }, []);
  useEffect(() => {
    let cancelled = false;
    fetch("/api/finance", { cache: "no-store" }).then(async (response) => {
      const json = await response.json();
      if (!response.ok) throw new Error(json.error);
      if (!cancelled) setData(json);
    }).catch((error) => { if (!cancelled) setMessage(error.message); });
    return () => { cancelled = true; };
  }, []);
  async function submit(endpoint: string, body: Row, done = "تم الحفظ") { setBusy(true); setMessage(""); try { const response = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const json = await response.json(); if (!response.ok) throw new Error(json.error); setMessage(done); await load(); return json; } catch (error) { setMessage(error instanceof Error ? error.message : "تعذر تنفيذ العملية"); } finally { setBusy(false); } }
  async function action(id: unknown, value: string) { setBusy(true); try { const response = await fetch(`/api/finance/vouchers/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: value }) }); const json = await response.json(); if (!response.ok) throw new Error(json.error); setMessage(value === "POST" ? "تم ترحيل السند" : "تم إلغاء السند وعكس أثره"); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : "تعذر التنفيذ"); } finally { setBusy(false); } }
  function reportParams(format?:string){const params=new URLSearchParams({report:reportName});if(reportFrom)params.set("from",reportFrom);if(reportTo)params.set("to",reportTo);if(reportAccountId)params.set("accountId",reportAccountId);if(reportBudgetId)params.set("budgetId",reportBudgetId);if(format)params.set("format",format);return params;}
  async function runReport() { const response = await fetch(`/api/finance/reports?${reportParams()}`, { cache: "no-store" }); const json = await response.json(); if(!response.ok){setMessage(json.error);return;} setReport(json); }
  if (!data) return <div className="mx-auto max-w-7xl p-8">{message || "جارٍ تحميل البيانات المالية…"}</div>;
  const tabs = [["overview","الملخص"],["receivables","ذمم العملاء"],["payables","ذمم الموردين"],["vouchers","سندات القبض والصرف"],["creditNotes","الإشعارات الدائنة/المدينة"],["adjustments","التسويات والاستحقاقات"],["banks","البنوك والتحويلات"],["reconciliation","التسوية البنكية"],["vatReturns","الإقرارات الضريبية"],["currencies","العملات وإعادة التقييم"],["budgets","الميزانيات"],["expenses","المصروفات والإيرادات"],["journals","القيود والفترات"],["reports","التقارير"]];
  return <div className="finance-workspace mx-auto max-w-7xl p-4 md:p-6">
    {message && <div className={`mb-4 rounded-lg p-3 ${message.startsWith("تم") ? "bg-emerald-50 text-emerald-800" : "bg-amber-50 text-amber-900"}`}>{message}</div>}
    <div className="finance-tabs mb-6">{tabs.map(([key,label]) => <button key={key} onClick={() => setTab(key)} className={tab === key ? "is-active" : ""}>{label}</button>)}</div>
    {tab === "overview" && <OverviewPanel data={data} />}
    {tab === "receivables" && <AgingPanel title="أعمار ديون العملاء" report={data.receivables} />}
    {tab === "payables" && <AgingPanel title="أعمار ديون الموردين" report={data.payables} />}
    {tab === "vouchers" && <div className="grid gap-6 xl:grid-cols-[380px_1fr]"><VoucherForm data={data} busy={busy} submit={submit} /><VoucherTable rows={data.recentVouchers} busy={busy} action={action} /></div>}
    {tab === "creditNotes" && <CreditDebitNotesPanel data={data} busy={busy} submit={submit} reload={load} setMessage={setMessage}/>}
    {tab === "adjustments" && <AdjustmentsPanel data={data} busy={busy} submit={submit} reload={load} setMessage={setMessage}/>}
    {tab === "banks" && <BankWorkspace data={data} busy={busy} submit={submit} setMessage={setMessage}/>}
    {tab === "reconciliation" && <BankReconciliationPanel data={data} busy={busy} submit={submit} reload={load} setMessage={setMessage} />}
    {tab === "vatReturns" && <VatReturnsPanel data={data} busy={busy} submit={submit} reload={load} setMessage={setMessage} />}
    {tab === "currencies" && <CurrencyPanel data={data} busy={busy} submit={submit} reload={load} setMessage={setMessage}/>}
    {tab === "budgets" && <BudgetPanel data={data} busy={busy} submit={submit} reload={load} setMessage={setMessage}/>}
    {tab === "expenses" && <MoneyWorkspace data={data} busy={busy} submit={submit} />}
    {tab === "journals" && <JournalsPanel data={data} busy={busy} submit={submit} setMessage={setMessage} />}
    {tab === "reports" && <div className="rounded-2xl border bg-white p-5"><div className="mb-5 grid gap-3 md:grid-cols-2 xl:grid-cols-6"><select className={input} value={reportName} onChange={(e) => setReportName(e.target.value)}><option value="profit-and-loss">قائمة الدخل</option><option value="balance-sheet">الميزانية العمومية</option><option value="cash-flow">التدفق النقدي</option><option value="changes-in-equity">التغيرات في حقوق الملكية</option><option value="trial-balance">ميزان المراجعة</option><option value="general-ledger">دفتر الأستاذ</option><option value="account-statement">كشف حساب تفصيلي</option><option value="vat">ضريبة القيمة المضافة</option><option value="ar-aging">أعمار ديون العملاء</option><option value="ap-aging">أعمار ديون الموردين</option><option value="budget-vs-actual">الفعلي مقابل الميزانية</option></select><input type="date" value={reportFrom} onChange={e=>setReportFrom(e.target.value)} className={input} aria-label="من تاريخ"/><input type="date" value={reportTo} onChange={e=>setReportTo(e.target.value)} className={input} aria-label="إلى تاريخ"/><select value={reportAccountId} onChange={e=>setReportAccountId(e.target.value)} className={input}><option value="">كل الحسابات</option>{data.accounts.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><select value={reportBudgetId} onChange={e=>setReportBudgetId(e.target.value)} className={input}><option value="">اختر ميزانية للتقرير</option>{data.budgets.filter(row=>row.status==="APPROVED").map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><button onClick={runReport} className="rounded-lg bg-slate-900 px-5 py-2 text-white">إعداد التقرير</button></div>{report && <><div className="mb-3 flex justify-end gap-2"><button onClick={()=>window.open(`/api/finance/reports/export?${reportParams("pdf")}`,"_blank")} className="rounded border px-3 py-1 text-sm">PDF / طباعة احترافية</button><button onClick={()=>window.open(`/api/finance/reports/export?${reportParams("xlsx")}`,"_blank")} className="rounded border px-3 py-1 text-sm">Excel حقيقي</button></div><ReportResult data={report}/></>}</div>}
  </div>;
}

function OverviewPanel({ data }: { data: Overview }) { const cards: [string, unknown][] = [["أرصدة البنوك",data.banks.reduce((sum,row) => sum + Number(row.currentBalance),0)],["ذمم العملاء",data.receivables.totals.total],["ذمم الموردين",data.payables.totals.total],["صافي الربح",data.statements.profitAndLoss.netProfit],["صافي التدفق النقدي",data.cash.totals.net]]; return <><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5">{cards.map(([label,value]) => <div key={label} className="rounded-2xl border bg-white p-5 shadow-sm"><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-xl font-bold">{money(value)}</p></div>)}</div><div className="mt-6 grid gap-5 lg:grid-cols-2"><AgingPanel title="أكبر ذمم العملاء" report={{...data.receivables, items:data.receivables.items.slice(0,5)}} /><AgingPanel title="أكبر ذمم الموردين" report={{...data.payables, items:data.payables.items.slice(0,5)}} /></div></> }
function AgingPanel({ title, report }: { title: string; report: { items: Row[]; totals: Row } }) { return <div className="rounded-2xl border bg-white p-5"><div className="mb-4 flex justify-between"><h2 className="font-bold">{title}</h2><strong>{money(report.totals.total)}</strong></div><SimpleTable heads={["الجهة","الفاتورة","الاستحقاق","العمر","المتبقي"]} rows={report.items.map((row) => [row.partyName,row.number,date(row.dueDate),`${row.ageDays} يوم`,money(row.outstanding)])} empty="لا توجد أرصدة مستحقة" /></div> }
function SimpleTable({ heads, rows, empty="لا توجد بيانات" }: { heads: string[]; rows: unknown[][]; empty?: string }) { return <div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-100"><tr>{heads.map((head) => <th className="p-3 text-right" key={head}>{head}</th>)}</tr></thead><tbody>{rows.map((row,i) => <tr className="border-b" key={i}>{row.map((cell,j) => <td className="p-3" key={j}>{isValidElement(cell)?cell:String(cell ?? "—")}</td>)}</tr>)}</tbody></table>{!rows.length && <p className="p-6 text-center text-slate-500">{empty}</p>}</div> }
function BankForm({ busy, submit }: { busy: boolean; submit: (url:string,body:Row,done?:string)=>Promise<unknown> }) { async function send(e:FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); const result = await submit("/api/finance/banks",Object.fromEntries(f),"تم إنشاء الحساب البنكي وربطه بدليل الحسابات"); if (result) e.currentTarget.reset(); } return <form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">حساب بنكي/نقدي جديد</h2><input name="name" required placeholder="اسم الحساب" className={input}/><input name="bankName" placeholder="اسم البنك" className={input}/><input name="iban" placeholder="IBAN" className={input}/><select name="currency" className={input}><option>SAR</option><option>USD</option></select><input name="openingBalance" type="number" step="0.01" min="0" defaultValue="0" className={input}/><button disabled={busy} className="w-full rounded-lg bg-blue-600 py-2 text-white">حفظ</button></form> }
function BankWorkspace({data,busy,submit,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;setMessage:(value:string)=>void}) {
  const [filters,setFilters]=useState({bankAccountId:String(data.banks[0]?.id??""),from:"",to:"",transactionType:"",q:""});
  const [ledger,setLedger]=useState<Row[]>([]),[loading,setLoading]=useState(false);
  const query=useMemo(()=>{const p=new URLSearchParams();Object.entries(filters).forEach(([key,value])=>value&&p.set(key,value));return p.toString();},[filters]);
  useEffect(()=>{if(!filters.bankAccountId)return;let cancelled=false;fetch(`/api/finance/banks?${query}`,{cache:"no-store"}).then(async response=>{const json=await response.json();if(!response.ok)throw new Error(json.error);if(!cancelled)setLedger(Array.isArray(json)&&json[0]?.transactions?json[0].transactions:[]);}).catch(error=>{if(!cancelled)setMessage(error instanceof Error?error.message:"تعذر تحميل كشف البنك");}).finally(()=>{if(!cancelled)setLoading(false);});return()=>{cancelled=true};},[filters.bankAccountId,query,setMessage]);
  const bank=data.banks.find(row=>String(row.id)===filters.bankAccountId);
  return <div className="space-y-6"><div className="grid gap-6 xl:grid-cols-[380px_1fr]"><BankForm busy={busy} submit={submit}/><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 text-lg font-bold">الحسابات البنكية والنقدية</h2><SimpleTable heads={["الحساب","البنك","العملة","الرصيد"]} rows={data.banks.map(row=>[row.name,row.bankName??"—",row.currency,money(row.currentBalance)])}/></div></div><section className="rounded-2xl border bg-white p-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-bold">كشف حركات البنك</h2><p className="text-xs text-slate-500">{String(bank?.name??"اختر حسابًا")} · {ledger.length.toLocaleString("en-US")} حركة مطابقة للفلاتر</p></div><div className="flex gap-2"><button onClick={()=>window.print()} className="rounded-lg border px-3 py-2 text-sm">طباعة</button><button onClick={()=>window.open(`/api/finance/banks?${query}&format=csv`,"_blank")} className="rounded-lg bg-slate-950 px-3 py-2 text-sm text-white">تصدير CSV</button></div></div><div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-5"><select value={filters.bankAccountId} onChange={e=>setFilters({...filters,bankAccountId:e.target.value})} className={input}><option value="">كل الحسابات</option>{data.banks.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><input type="date" value={filters.from} onChange={e=>setFilters({...filters,from:e.target.value})} className={input}/><input type="date" value={filters.to} onChange={e=>setFilters({...filters,to:e.target.value})} className={input}/><select value={filters.transactionType} onChange={e=>setFilters({...filters,transactionType:e.target.value})} className={input}><option value="">كل الأنواع</option><option value="CUSTOMER_RECEIPT">قبض عميل</option><option value="SUPPLIER_PAYMENT">صرف مورد</option><option value="TRANSFER_IN">تحويل وارد</option><option value="TRANSFER_OUT">تحويل صادر</option><option value="EXPENSE">مصروف</option><option value="REVENUE">إيراد</option></select><input value={filters.q} onChange={e=>setFilters({...filters,q:e.target.value})} placeholder="مرجع أو بيان" className={input}/></div>{loading?<p className="p-8 text-center text-slate-500">جارٍ تحميل الحركات…</p>:<SimpleTable heads={["التاريخ","النوع","المرجع","البيان","وارد","صادر","الرصيد"]} rows={ledger.map(row=>[date(row.transactionDate),row.transactionType,row.referenceNumber,row.description,money(row.amountIn),money(row.amountOut),money(row.balanceAfter)])} empty="لا توجد حركات ضمن الفلاتر المحددة"/>}</section><div className="grid gap-6 xl:grid-cols-[380px_1fr]"><TransferForm data={data} busy={busy} submit={submit}/><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">التحويلات البنكية</h2><SimpleTable heads={["الرقم","التاريخ","من","إلى","المبلغ","الرسوم","الحالة"]} rows={data.transfers.map(row=>[row.transferNumber,date(row.transferDate),(row.fromBankAccount as Row)?.name,(row.toBankAccount as Row)?.name,money(row.amount),money(row.fees),row.status])}/></div></div></div>;
}
function TransferForm({data,busy,submit}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>}) { async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,row=await submit("/api/finance/transfers",Object.fromEntries(new FormData(form)),"تم التحويل وإثبات طرفيه والقيد المحاسبي");if(row)form.reset();} return <form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">تحويل بين الحسابات</h2><input type="date" name="transferDate" required defaultValue={new Date().toISOString().slice(0,10)} className={input}/><select name="fromBankAccountId" required className={input}><option value="">من حساب</option>{data.banks.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><select name="toBankAccountId" required className={input}><option value="">إلى حساب</option>{data.banks.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><input name="amount" type="number" min="0.01" step="0.01" required placeholder="المبلغ" className={input}/><input name="fees" type="number" min="0" step="0.01" defaultValue="0" placeholder="رسوم البنك" className={input}/><input name="description" placeholder="البيان" className={input}/><button disabled={busy} className="w-full rounded-lg bg-indigo-600 py-2 text-white">تنفيذ التحويل</button></form> }
function VoucherForm({ data, busy, submit }: { data:Overview; busy:boolean; submit:(url:string,body:Row,done?:string)=>Promise<unknown> }) { const [type,setType]=useState("CUSTOMER_RECEIPT"), [partyId,setPartyId]=useState(""); const invoiceRows=(type==="CUSTOMER_RECEIPT"?data.receivables.items:data.payables.items).filter((row)=>String(row.partyId)===partyId); async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form), invoiceId=Number(f.get("invoiceId")), allocationAmount=Number(f.get("allocationAmount")),file=f.get("attachment") instanceof File?f.get("attachment") as File:null; const body:Row=Object.fromEntries(f);delete body.attachment; body.voucherType=type; body.allocations=invoiceId&&allocationAmount?[type==="CUSTOMER_RECEIPT"?{saleId:invoiceId,amount:allocationAmount}:{purchaseId:invoiceId,amount:allocationAmount}]:[]; const row=await submit("/api/finance/vouchers",body,"تم إنشاء السند كمسودة؛ رحّله من الجدول لإثبات أثره"); if(row){await uploadAttachment("FINANCIAL_VOUCHER",(row as Row).id,file);form.reset();}} const parties=data.parties.filter((row)=>type==="CUSTOMER_RECEIPT"?row.isCustomer:row.isSupplier); return <form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">سند قبض/صرف</h2><select value={type} onChange={(e)=>{setType(e.target.value);setPartyId("")}} className={input}><option value="CUSTOMER_RECEIPT">قبض من عميل</option><option value="SUPPLIER_PAYMENT">دفع لمورد</option></select><select name="partyId" required value={partyId} onChange={(e)=>setPartyId(e.target.value)} className={input}><option value="">اختر الجهة</option>{parties.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.nameAr)}</option>)}</select><select name="bankAccountId" required className={input}><option value="">الحساب البنكي</option>{data.banks.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)} — {money(row.currentBalance)}</option>)}</select><input name="amount" required type="number" min="0.01" step="0.01" placeholder="المبلغ" className={input}/><select name="invoiceId" className={input}><option value="">بدون تخصيص</option>{invoiceRows.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.number)} — {money(row.outstanding)}</option>)}</select><input name="allocationAmount" type="number" min="0" step="0.01" placeholder="المبلغ المخصص للفاتورة" className={input}/><input name="referenceNumber" placeholder="رقم المرجع" className={input}/><input name="attachment" type="file" accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx" className={input}/><button disabled={busy} className="w-full rounded-lg bg-blue-600 py-2 text-white">إنشاء السند</button></form> }
function VoucherTable({rows,busy,action}:{rows:Row[];busy:boolean;action:(id:unknown,value:string)=>void}) { return <div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">السندات الأخيرة</h2><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="bg-slate-100"><th className="p-3">الرقم</th><th>النوع</th><th>الجهة</th><th>المبلغ</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{rows.map((row)=><tr className="border-b" key={String(row.id)}><td className="p-3">{String(row.voucherNumber)}</td><td>{row.voucherType==="CUSTOMER_RECEIPT"?"قبض":"صرف"}</td><td>{String((row.party as Row)?.nameAr??"—")}</td><td>{money(row.amount)}</td><td>{String(row.status)}</td><td className="space-x-2 space-x-reverse"><a href={`/accounting/vouchers/${row.id}/print`} target="_blank" className="rounded border border-amber-300 px-3 py-1 text-amber-800">طباعة</a>{row.status==="DRAFT"&&<button disabled={busy} onClick={()=>action(row.id,"POST")} className="rounded bg-emerald-600 px-3 py-1 text-white">ترحيل</button>}{row.status==="POSTED"&&<button disabled={busy} onClick={()=>action(row.id,"CANCEL")} className="rounded bg-red-600 px-3 py-1 text-white">إلغاء وعكس</button>}</td></tr>)}</tbody></table></div></div> }
function MoneyForm({kind,data,busy,submit}:{kind:"expense"|"revenue";data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>}) { const expense=kind==="expense", categories=expense?data.expenseCategories:data.revenueCategories; async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),file=f.get("attachment") instanceof File?f.get("attachment") as File:null,body:Row=Object.fromEntries(f);delete body.attachment;if(expense){body.allocations=data.costCenters.map(row=>({costCenterId:Number(row.id),percentage:Number(f.get(`allocation_${row.id}`)??0)})).filter(row=>row.percentage>0);for(const row of data.costCenters)delete body[`allocation_${row.id}`];}const row=await submit(`/api/finance/${expense?"expenses":"revenues"}`,body,`تم ترحيل ${expense?"المصروف":"الإيراد"} وإثبات حركة البنك`);if(row){await uploadAttachment(expense?"EXPENSE":"REVENUE",(row as Row).id,file);form.reset();}} return <form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">{expense?"إثبات مصروف":"إثبات إيراد"}</h2><input type="date" name={expense?"expenseDate":"revenueDate"} required defaultValue={new Date().toISOString().slice(0,10)} className={input}/><select name="categoryId" required className={input}><option value="">التصنيف</option>{categories.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.nameAr)}</option>)}</select><select name="bankAccountId" required className={input}><option value="">الحساب البنكي</option>{data.banks.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><input name="amountBeforeVat" type="number" min="0.01" step="0.01" required placeholder="المبلغ قبل الضريبة" className={input}/><input name="vatAmount" type="number" min="0" step="0.01" defaultValue="0" placeholder="الضريبة" className={input}/><input name="description" required placeholder="البيان" className={input}/>{expense?<fieldset className="rounded-lg border p-3"><legend className="px-2 text-sm font-bold">توزيع مراكز التكلفة — المجموع 100٪</legend><div className="grid gap-2 sm:grid-cols-2">{data.costCenters.map(row=><label key={String(row.id)} className="text-xs text-slate-600">{String(row.nameAr)}<input name={`allocation_${row.id}`} type="number" min="0" max="100" step="0.01" defaultValue={row.code==="ADMIN"?100:0} className={input}/></label>)}</div></fieldset>:<select name="costCenter" className={input}><option value="">مركز الربح</option>{data.costCenters.map((row)=><option key={String(row.code)} value={String(row.code)}>{String(row.nameAr)}</option>)}</select>}<input name="attachment" type="file" accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx" className={input}/><button disabled={busy} className={`w-full rounded-lg py-2 text-white ${expense?"bg-rose-600":"bg-emerald-600"}`}>حفظ وترحيل</button></form> }

function MoneyWorkspace({data,busy,submit}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>}) {
  const [view,setView]=useState<"expense"|"revenue">("expense");
  const rows=view==="expense"?data.ledgerExpenses:data.ledgerRevenues;
  const total=rows.reduce((sum,row)=>sum+Number(view==="expense"?row.debit:row.credit),0);
  return <div className="space-y-6"><div className="grid gap-6 lg:grid-cols-2"><MoneyForm kind="expense" data={data} busy={busy} submit={submit}/><MoneyForm kind="revenue" data={data} busy={busy} submit={submit}/></div><section className="rounded-2xl border bg-white p-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-bold">السجل الفعلي من الأستاذ العام</h2><p className="text-xs text-slate-500">يشمل البيانات المرحلة والمستوردة، بدون إنشاء إدخالات مكررة.</p></div><div className="flex rounded-xl bg-slate-100 p-1"><button onClick={()=>setView("expense")} className={`rounded-lg px-4 py-2 text-sm ${view==="expense"?"bg-slate-950 text-white":""}`}>المصروفات</button><button onClick={()=>setView("revenue")} className={`rounded-lg px-4 py-2 text-sm ${view==="revenue"?"bg-slate-950 text-white":""}`}>الإيرادات</button></div></div><div className="mb-3 rounded-xl bg-amber-50 p-3 text-sm font-bold text-amber-950">الإجمالي الظاهر: {money(total)} · {rows.length.toLocaleString("en-US")} حركة</div><SimpleTable heads={["التاريخ","رقم القيد","الحساب","البيان","المرجع","القيمة"]} rows={rows.map(row=>[date((row.journalEntry as Row)?.entryDate),(row.journalEntry as Row)?.entryNumber,(row.account as Row)?.nameAr,row.description??(row.journalEntry as Row)?.description,(row.journalEntry as Row)?.referenceNumber,money(view==="expense"?row.debit:row.credit)])} empty={`لا توجد حركات ${view==="expense"?"مصروفات":"إيرادات"} مرحلة`}/></section></div>;
}
function JournalsPanel({data,busy,submit,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;setMessage:(value:string)=>void}) { async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),amount=Number(f.get("amount"));const row=await submit("/api/accounting",{entryDate:f.get("entryDate"),description:f.get("description"),referenceNumber:f.get("referenceNumber"),lines:[{accountId:Number(f.get("debitAccountId")),debit:amount},{accountId:Number(f.get("creditAccountId")),credit:amount}]},"تم ترحيل القيد اليدوي");if(row)form.reset();} return <div className="space-y-6"><div className="grid gap-6 xl:grid-cols-[380px_1fr]"><form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">قيد يدوي متوازن</h2><input type="date" name="entryDate" required defaultValue={new Date().toISOString().slice(0,10)} className={input}/><input name="description" required placeholder="بيان القيد" className={input}/><input name="referenceNumber" placeholder="المرجع" className={input}/><select name="debitAccountId" required className={input}><option value="">الحساب المدين</option>{data.accounts.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><select name="creditAccountId" required className={input}><option value="">الحساب الدائن</option>{data.accounts.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><input name="amount" type="number" min="0.01" step="0.01" required placeholder="المبلغ" className={input}/><button disabled={busy} className="w-full rounded-lg bg-slate-900 py-2 text-white">ترحيل القيد</button></form><FiscalCalendarPanel setMessage={setMessage}/></div><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">آخر القيود</h2><SimpleTable heads={["الرقم","التاريخ","البيان","المرجع","مدين","دائن","الحالة"]} rows={data.journals.map((row)=>[row.entryNumber,date(row.entryDate),row.description,row.referenceNumber,money(row.totalDebit),money(row.totalCredit),row.status])}/></div></div> }

function FiscalCalendarPanel({setMessage}:{setMessage:(value:string)=>void}) {
  const [calendar,setCalendar]=useState<Row|null>(null);
  const loadCalendar=useCallback(async()=>{const response=await fetch("/api/finance/fiscal-calendar",{cache:"no-store"}),json=await response.json();if(!response.ok)throw new Error(json.error);setCalendar(json);},[]);
  useEffect(()=>{let cancelled=false;fetch("/api/finance/fiscal-calendar",{cache:"no-store"}).then(async response=>{const json=await response.json();if(!response.ok)throw new Error(json.error);if(!cancelled)setCalendar(json);}).catch(error=>{if(!cancelled)setMessage(error.message);});return()=>{cancelled=true;};},[setMessage]);
  async function action(kind:"period"|"year",id:unknown,value:"CLOSE"|"REOPEN"){let reason=value==="REOPEN"?window.prompt("اكتب سبب إعادة الفتح (يسجل في Audit Log)",""):undefined;if(value==="REOPEN"&&!reason)return;const endpoint=kind==="period"?`/api/finance/fiscal-periods/${id}`:`/api/finance/fiscal-years/${id}`;let response=await fetch(endpoint,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:value,reason})}),json=await response.json();if(!response.ok&&value==="CLOSE"&&kind==="period"&&Array.isArray(json.blockers)&&json.blockers.length){reason=window.prompt(`توجد تحذيرات:\n${json.blockers.join("\n")}\n\nللموافقة الاستثنائية اكتب السبب:` ,"")??undefined;if(!reason)return;response=await fetch(endpoint,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:value,overrideWarnings:true,reason})});json=await response.json();}if(!response.ok){setMessage([json.error,...(json.blockers??[])].join(" — "));return;}setMessage(value==="CLOSE"?`تم إغلاق ${kind==="year"?"السنة":"الفترة"} وتسجيل الأثر المحاسبي`:`تمت إعادة الفتح مع تسجيل السبب`);await loadCalendar();}
  if(!calendar)return <div className="rounded-2xl border bg-white p-5">جارٍ تحميل التقويم المالي…</div>;
  const periods=Array.isArray(calendar.periods)?calendar.periods as Row[]:[];
  return <div className="rounded-2xl border bg-white p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-bold">{String(calendar.name)}</h2><p className="text-xs text-slate-500">{date(calendar.startDate)} — {date(calendar.endDate)} · {String(calendar.status)}</p></div><button onClick={()=>action("year",calendar.id,calendar.status==="OPEN"?"CLOSE":"REOPEN")} className={`rounded px-3 py-2 text-white ${calendar.status==="OPEN"?"bg-slate-900":"bg-amber-600"}`}>{calendar.status==="OPEN"?"إقفال السنة":"إعادة فتح السنة"}</button></div><div className="max-h-80 space-y-2 overflow-auto">{periods.map(row=><div key={String(row.id)} className="flex items-center justify-between rounded-lg border p-3"><div><strong>{String(row.periodNumber)}. {String(row.name)}</strong><p className="text-xs text-slate-500">{String(row.status)}{Array.isArray(row.blockers)&&row.blockers.length?` · ${row.blockers.join("، ")}`:" · جاهزة للإغلاق"}</p></div><button disabled={calendar.status!=="OPEN"} onClick={()=>action("period",row.id,row.status==="OPEN"?"CLOSE":"REOPEN")} className={`rounded px-3 py-1 text-white disabled:opacity-40 ${row.status==="OPEN"?"bg-rose-600":"bg-emerald-600"}`}>{row.status==="OPEN"?"إغلاق":"فتح"}</button></div>)}</div></div>;
}

function CreditDebitNotesPanel({data,busy,submit,reload,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;reload:()=>Promise<void>;setMessage:(value:string)=>void}) {
  const [direction,setDirection]=useState("SALES");
  async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),sourceId=Number(f.get("sourceId")),body:Row=Object.fromEntries(f);body.direction=direction;if(direction==="SALES")body.saleId=sourceId;else body.purchaseId=sourceId;delete body.sourceId;const row=await submit("/api/finance/credit-debit-notes",body,"تم إنشاء الإشعار كمسودة ومراجعته مقابل الفاتورة");if(row)form.reset();}
  async function noteAction(id:unknown,value:"POST"|"CANCEL"){const reason=value==="CANCEL"?window.prompt("سبب الإلغاء",""):undefined;if(value==="CANCEL"&&!reason)return;const response=await fetch(`/api/finance/credit-debit-notes/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:value,reason})}),json=await response.json();if(!response.ok){setMessage(json.error);return;}setMessage(value==="POST"?"تم ترحيل الإشعار وتحديث الذمم والضريبة":"تم إلغاء الإشعار وعكس قيده");await reload();}
  const invoices=direction==="SALES"?data.salesInvoices:data.purchaseInvoices;
  return <div className="grid gap-6 xl:grid-cols-[400px_1fr]"><form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">إشعار مالي مرتبط بفاتورة</h2><select value={direction} onChange={e=>setDirection(e.target.value)} className={input}><option value="SALES">مبيعات / عميل</option><option value="PURCHASE">مشتريات / مورد</option></select><select name="noteType" required className={input}><option value="CREDIT_NOTE">إشعار دائن — تخفيض الفاتورة</option><option value="DEBIT_NOTE">إشعار مدين — زيادة الفاتورة</option></select><select name="sourceId" required className={input}><option value="">الفاتورة الأصلية</option>{invoices.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.invoiceNumber??row.purchaseNumber)} — {money(row.totalAmount)}</option>)}</select><input type="date" name="noteDate" required defaultValue={new Date().toISOString().slice(0,10)} className={input}/><input name="amountBeforeVat" type="number" min="0.01" step="0.01" required placeholder="المبلغ قبل الضريبة" className={input}/><input name="vatAmount" type="number" min="0" step="0.01" defaultValue="0" placeholder="الضريبة" className={input}/><input name="reason" required placeholder="سبب الإشعار" className={input}/><textarea name="notes" placeholder="ملاحظات" className={input}/><button disabled={busy} className="w-full rounded-lg bg-indigo-600 py-2 text-white">إنشاء المسودة</button></form><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">سجل الإشعارات</h2><SimpleTable heads={["الرقم","التاريخ","النوع","الاتجاه","الجهة","الإجمالي","الحالة","الإجراء"]} rows={data.creditDebitNotes.map(row=>[row.noteNumber,date(row.noteDate),row.noteType==="CREDIT_NOTE"?"دائن":"مدين",row.direction==="SALES"?"مبيعات":"مشتريات",(row.party as Row)?.nameAr,money(row.totalAmount),row.status,<span key={String(row.id)} className="space-x-2 space-x-reverse">{row.status==="DRAFT"&&<button onClick={()=>noteAction(row.id,"POST")} className="rounded bg-emerald-600 px-2 py-1 text-white">ترحيل</button>}{row.status==="POSTED"&&<button onClick={()=>noteAction(row.id,"CANCEL")} className="rounded bg-rose-600 px-2 py-1 text-white">إلغاء</button>}</span>])}/></div></div>;
}

function AdjustmentsPanel({data,busy,submit,reload,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;reload:()=>Promise<void>;setMessage:(value:string)=>void}) {
  async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),amount=Number(f.get("amount")),body:Row=Object.fromEntries(f);body.lines=[{accountId:Number(f.get("debitAccountId")),debit:amount},{accountId:Number(f.get("creditAccountId")),credit:amount}];delete body.amount;delete body.debitAccountId;delete body.creditAccountId;const row=await submit("/api/finance/adjustments",body,"تم إنشاء قيد التسوية كمسودة متوازنة");if(row)form.reset();}
  async function adjustmentAction(id:unknown,value:"POST"|"CANCEL"){const reason=value==="CANCEL"?window.prompt("سبب الإلغاء",""):undefined;if(value==="CANCEL"&&!reason)return;const response=await fetch(`/api/finance/adjustments/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:value,reason})}),json=await response.json();if(!response.ok){setMessage(json.error);return;}setMessage(value==="POST"?"تم ترحيل قيد التسوية":"تم إلغاء التسوية وعكس القيد");await reload();}
  return <div className="grid gap-6 xl:grid-cols-[400px_1fr]"><form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">قيد تسوية/استحقاق</h2><select name="adjustmentType" required className={input}><option value="ACCRUAL">استحقاق</option><option value="PREPAYMENT">مصروف/إيراد مقدم</option><option value="OPENING_BALANCE">رصيد افتتاحي</option><option value="ADJUSTMENT">تسوية عامة</option></select><input type="date" name="adjustmentDate" required defaultValue={new Date().toISOString().slice(0,10)} className={input}/><input name="description" required placeholder="بيان التسوية" className={input}/><input name="referenceNumber" placeholder="المرجع" className={input}/><select name="debitAccountId" required className={input}><option value="">الحساب المدين</option>{data.accounts.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><select name="creditAccountId" required className={input}><option value="">الحساب الدائن</option>{data.accounts.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><input name="amount" type="number" min="0.01" step="0.01" required placeholder="المبلغ" className={input}/><textarea name="notes" placeholder="ملاحظات" className={input}/><button disabled={busy} className="w-full rounded-lg bg-slate-900 py-2 text-white">إنشاء المسودة</button></form><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">قيود التسوية</h2><SimpleTable heads={["الرقم","التاريخ","النوع","البيان","المبلغ","الحالة","الإجراء"]} rows={data.adjustments.map(row=>[row.adjustmentNumber,date(row.adjustmentDate),row.adjustmentType,row.description,money(Array.isArray(row.lines)?(row.lines as Row[]).reduce((sum,line)=>sum+Number(line.debit),0):0),row.status,<span key={String(row.id)} className="space-x-2 space-x-reverse">{row.status==="DRAFT"&&<button onClick={()=>adjustmentAction(row.id,"POST")} className="rounded bg-emerald-600 px-2 py-1 text-white">ترحيل</button>}{row.status==="POSTED"&&<button onClick={()=>adjustmentAction(row.id,"CANCEL")} className="rounded bg-rose-600 px-2 py-1 text-white">إلغاء</button>}</span>])}/></div></div>;
}

function BankReconciliationPanel({data,busy,submit,reload,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;reload:()=>Promise<void>;setMessage:(value:string)=>void}) {
  const [bankId,setBankId]=useState(""),[candidates,setCandidates]=useState<Row[]>([]),[selected,setSelected]=useState<number[]>([]);
  useEffect(()=>{if(!bankId)return;fetch(`/api/finance/reconciliations?bankAccountId=${bankId}`,{cache:"no-store"}).then(async response=>{const json=await response.json();if(!response.ok)throw new Error(json.error);setCandidates(json.candidates);setSelected(json.candidates.map((row:Row)=>Number(row.id)));}).catch(error=>setMessage(error.message));},[bankId,setMessage]);
  async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,body:Row=Object.fromEntries(new FormData(form));body.transactionIds=selected;const row=await submit("/api/finance/reconciliations",body,"تم إنشاء مسودة التسوية وحساب الفرق");if(row){form.reset();setBankId("");}}
  async function reconciliationAction(id:unknown,action:"COMPLETE"|"DELETE"){if(action==="DELETE"&&!window.confirm("حذف مسودة التسوية وإتاحة الحركات للمطابقة من جديد؟"))return;const response=await fetch(`/api/finance/reconciliations/${id}`,action==="DELETE"?{method:"DELETE"}:{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"COMPLETE"})}),json=await response.json();if(!response.ok){setMessage(json.error);return;}setMessage(action==="COMPLETE"?"تم إقفال التسوية البنكية دون فرق":"تم حذف المسودة وإتاحة حركاتها من جديد");await reload();}
  return <div className="space-y-6"><div className="grid gap-6 xl:grid-cols-[420px_1fr]"><form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">تسوية كشف بنكي</h2><select name="bankAccountId" required value={bankId} onChange={e=>{setBankId(e.target.value);setCandidates([]);setSelected([]);}} className={input}><option value="">اختر الحساب</option>{data.banks.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><div className="grid grid-cols-2 gap-2"><input name="periodStart" type="date" required className={input}/><input name="periodEnd" type="date" required className={input}/></div><input name="statementOpeningBalance" type="number" step="0.01" required placeholder="رصيد كشف أول المدة" className={input}/><input name="statementClosingBalance" type="number" step="0.01" required placeholder="رصيد كشف آخر المدة" className={input}/><textarea name="notes" placeholder="ملاحظات" className={input}/><button disabled={busy||!bankId} className="w-full rounded-lg bg-blue-600 py-2 text-white">إنشاء وحساب الفرق</button></form><div className="rounded-2xl border bg-white p-5"><div className="mb-3 flex items-center justify-between"><h2 className="font-bold">حركات ظهرت في كشف البنك</h2><span className="text-sm text-slate-500">{selected.length} محددة</span></div><div className="max-h-96 overflow-auto">{candidates.map(row=><label key={String(row.id)} className="flex cursor-pointer items-center gap-3 border-b p-3"><input type="checkbox" checked={selected.includes(Number(row.id))} onChange={e=>setSelected(old=>e.target.checked?[...old,Number(row.id)]:old.filter(id=>id!==Number(row.id)))}/><span className="flex-1">{date(row.transactionDate)} · {String(row.referenceNumber??row.transactionType)}</span><strong>{money(Number(row.amountIn)-Number(row.amountOut))}</strong></label>)}{!candidates.length&&<p className="p-8 text-center text-slate-500">اختر حسابًا لعرض الحركات غير المسواة</p>}</div></div></div><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">سجل التسويات</h2><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-100"><tr><th className="p-3">الرقم</th><th>الحساب</th><th>الفترة</th><th>رصيد الكشف</th><th>رصيد الدفتر</th><th>الفرق</th><th>الحالة</th><th></th></tr></thead><tbody>{data.reconciliations.map(row=><tr className="border-b" key={String(row.id)}><td className="p-3">{String(row.reconciliationNumber)}</td><td>{String((row.bankAccount as Row)?.name)}</td><td>{date(row.periodStart)} — {date(row.periodEnd)}</td><td>{money(row.statementClosingBalance)}</td><td>{money(row.bookClosingBalance)}</td><td className={Math.abs(Number(row.difference))>.004?"font-bold text-red-700":"font-bold text-emerald-700"}>{money(row.difference)}</td><td>{String(row.status)}</td><td>{row.status==="DRAFT"&&<span className="flex gap-2"><button onClick={()=>void reconciliationAction(row.id,"COMPLETE")} className="rounded bg-emerald-600 px-3 py-1 text-white">إقفال</button><button onClick={()=>void reconciliationAction(row.id,"DELETE")} className="rounded border border-red-300 px-3 py-1 text-red-700">حذف المسودة</button></span>}</td></tr>)}</tbody></table></div></div></div>;
}

function VatReturnsPanel({data,busy,submit,reload,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;reload:()=>Promise<void>;setMessage:(value:string)=>void}) {
  const [settlementBankId,setSettlementBankId]=useState(String(data.banks[0]?.id??""));
  async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,row=await submit("/api/finance/vat-returns",Object.fromEntries(new FormData(form)),"تم إنشاء مسودة الإقرار ومطابقة المستندات مع الأستاذ");if(row)form.reset();}
  async function action(row:Row,actionName:"FILE"|"SETTLE"){if(actionName==="SETTLE"&&!settlementBankId){setMessage("اختر حساب التسوية البنكية");return;}const response=await fetch(`/api/finance/vat-returns/${row.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:actionName,bankAccountId:Number(settlementBankId),settlementDate:new Date().toISOString().slice(0,10)})}),json=await response.json();if(!response.ok){setMessage(json.error);return;}setMessage(actionName==="FILE"?"تم تسجيل الإقرار كمقدم داخليًا وترحيل قيد التسوية":"تمت تسوية الإقرار وإثبات حركة البنك");await reload();}
  return <div className="space-y-6"><div className="grid gap-6 xl:grid-cols-[380px_1fr]"><form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">إقرار ضريبة قيمة مضافة</h2><p className="text-sm text-slate-500">ينشئ Snapshot من المستندات ويراجعه مع حسابات الضريبة في الأستاذ. التسجيل داخلي ولا يمثل إرسالًا آليًا إلى ZATCA.</p><input name="periodStart" type="date" required className={input}/><input name="periodEnd" type="date" required className={input}/><textarea name="notes" placeholder="ملاحظات الإقرار" className={input}/><button disabled={busy} className="w-full rounded-lg bg-indigo-600 py-2 text-white">إنشاء ومطابقة</button></form><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">دورة الإقرار</h2><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-4"><strong>1. مسودة</strong><p className="text-xs text-slate-500">تجميع المصادر وحفظ Snapshot</p></div><div className="rounded-xl bg-slate-50 p-4"><strong>2. اعتماد داخلي</strong><p className="text-xs text-slate-500">يتطلب فرقًا صفريًا وينشئ قيد التسوية</p></div><div className="rounded-xl bg-slate-50 p-4"><strong>3. سداد/استرداد</strong><p className="text-xs text-slate-500">قيد متوازن وحركة بنك موثقة</p></div></div><label className="mt-5 block text-sm font-medium">حساب السداد/الاسترداد</label><select value={settlementBankId} onChange={e=>setSettlementBankId(e.target.value)} className={input}><option value="">اختر الحساب البنكي</option>{data.banks.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.name)} — {money(row.currentBalance)}</option>)}</select></div></div><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">الإقرارات</h2><div className="space-y-3">{data.vatReturns.map(row=>{const lines=Array.isArray(row.lines)?row.lines as Row[]:[],from=String(row.periodStart).slice(0,10),to=String(row.periodEnd).slice(0,10);return <details className="rounded-xl border bg-white" key={String(row.id)}><summary className="grid cursor-pointer gap-2 p-4 sm:grid-cols-4 lg:grid-cols-8"><b>{String(row.returnNumber)}</b><span>{date(row.periodStart)} — {date(row.periodEnd)}</span><span>مخرجات {money(row.documentOutputVat)}</span><span>مدخلات {money(row.documentInputVat)}</span><strong>صافي {money(row.netVatDue)}</strong><span className={Number(row.variance)>.004?"font-bold text-red-700":"font-bold text-emerald-700"}>فرق {money(row.variance)}</span><span>{lines.length} مصدر</span><span>{String(row.status)}</span></summary><div className="border-t p-4"><div className="mb-3 flex flex-wrap gap-2"><button onClick={()=>window.open(`/api/finance/reports/export?report=vat&from=${from}&to=${to}&format=xlsx`,"_blank")} className="rounded border px-3 py-1">Excel</button><button onClick={()=>window.open(`/api/finance/reports/export?report=vat&from=${from}&to=${to}&format=pdf`,"_blank")} className="rounded border px-3 py-1">PDF / طباعة</button>{row.status==="DRAFT"&&<button onClick={()=>action(row,"FILE")} className="rounded bg-blue-600 px-3 py-1 text-white">اعتماد داخلي</button>}{row.status==="FILED"&&<button onClick={()=>action(row,"SETTLE")} className="rounded bg-emerald-600 px-3 py-1 text-white">تسوية بنكية</button>}</div><SimpleTable heads={["التاريخ","المصدر","الرقم","صافي الوعاء","ضريبة المستند","ضريبة الأستاذ","الفرق"]} rows={lines.map(line=>[date(line.sourceDate),line.sourceType,line.sourceNumber,money(line.netAmount),money(line.documentVat),money(line.ledgerVat),money(line.variance)])} empty="لا توجد مصادر ضريبية في هذه الفترة"/></div></details>})}{!data.vatReturns.length&&<p className="p-8 text-center text-slate-500">لا توجد إقرارات محفوظة. أنشئ إقرارًا لفترة محددة لعرض بياناتها الفعلية.</p>}</div></div></div>;
}

function CurrencyPanel({data,busy,submit,reload,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;reload:()=>Promise<void>;setMessage:(value:string)=>void}) {
  async function rate(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,row=await submit("/api/finance/exchange-rates",Object.fromEntries(new FormData(form)),"تم حفظ سعر الصرف في السجل التاريخي");if(row)form.reset();}
  async function revalue(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,row=await submit("/api/finance/fx-revaluations",Object.fromEntries(new FormData(form)),"تم إنشاء إعادة التقييم ومسح الأرصدة المفتوحة");if(row)form.reset();}
  async function fxAction(id:unknown,actionName:"POST"|"REVERSE"){const response=await fetch(`/api/finance/fx-revaluations/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:actionName})}),json=await response.json();if(!response.ok){setMessage(json.error);return;}setMessage(actionName==="POST"?"تم ترحيل فروق العملة غير المحققة":"تم عكس قيد إعادة التقييم في الفترة التالية");await reload();}
  return <div className="space-y-6"><div className="grid gap-6 lg:grid-cols-2"><form onSubmit={rate} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">سعر صرف تاريخي</h2><select name="baseCurrencyCode" required className={input}><option value="">عملة المعاملة</option>{data.currencies.map(row=><option key={String(row.code)} value={String(row.code)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><input name="quoteCurrencyCode" defaultValue="SAR" required placeholder="العملة الوظيفية" className={input}/><input name="rateDate" type="date" required className={input}/><input name="rate" type="number" min="0.00000001" step="0.00000001" required placeholder="قيمة وحدة عملة المعاملة بالعملة الوظيفية" className={input}/><input name="source" defaultValue="MANUAL" placeholder="المصدر" className={input}/><button disabled={busy} className="w-full rounded-lg bg-blue-600 py-2 text-white">حفظ السعر</button></form><form onSubmit={revalue} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">إعادة تقييم الأرصدة المفتوحة</h2><select name="currencyCode" required className={input}><option value="">العملة الأجنبية</option>{data.currencies.filter(row=>row.code!=="SAR").map(row=><option key={String(row.code)} value={String(row.code)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><input name="revaluationDate" type="date" required className={input}/><textarea name="notes" placeholder="ملاحظات المراجع" className={input}/><button disabled={busy} className="w-full rounded-lg bg-indigo-600 py-2 text-white">إنشاء المسودة</button></form></div><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">سجل أسعار الصرف</h2><SimpleTable heads={["التاريخ","من","إلى","السعر","المصدر"]} rows={data.exchangeRates.map(row=>[date(row.rateDate),row.baseCurrencyCode,row.quoteCurrencyCode,Number(row.rate).toFixed(6),row.source])}/></div><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">إعادات التقييم</h2><SimpleTable heads={["الرقم","التاريخ","العملة","السعر","ربح غير محقق","خسارة غير محققة","الحالة","الإجراء"]} rows={data.fxRevaluations.map(row=>[row.revaluationNumber,date(row.revaluationDate),row.currencyCode,Number(row.exchangeRate).toFixed(6),money(row.totalGain),money(row.totalLoss),row.status,<span key={String(row.id)} className="space-x-2 space-x-reverse">{row.status==="DRAFT"&&<button onClick={()=>fxAction(row.id,"POST")} className="rounded bg-emerald-600 px-2 py-1 text-white">ترحيل</button>}{row.status==="POSTED"&&<button onClick={()=>fxAction(row.id,"REVERSE")} className="rounded bg-rose-600 px-2 py-1 text-white">عكس</button>}</span>])}/></div></div>;
}

function BudgetPanel({data,busy,submit,reload,setMessage}:{data:Overview;busy:boolean;submit:(url:string,body:Row,done?:string)=>Promise<unknown>;reload:()=>Promise<void>;setMessage:(value:string)=>void}) {
  const [periodType,setPeriodType]=useState("MONTHLY"),[yearId,setYearId]=useState("");
  const periods=(data.fiscalYears.find(row=>String(row.id)===yearId)?.periods as Row[]|undefined)??[];
  async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),line:Row={accountId:Number(f.get("accountId")),periodType,amount:Number(f.get("amount")),costCenterId:f.get("costCenterId")?Number(f.get("costCenterId")):null,departmentId:f.get("departmentId")?Number(f.get("departmentId")):null,projectCode:f.get("projectCode")||null};if(periodType==="MONTHLY")line.fiscalPeriodId=Number(f.get("fiscalPeriodId"));const body:Row={name:f.get("name"),fiscalYearId:Number(f.get("fiscalYearId")),currencyCode:"SAR",notes:f.get("notes"),lines:[line]};const row=await submit("/api/finance/budgets",body,"تم إنشاء الميزانية السنوية/الشهرية بأبعادها");if(row)form.reset();}
  async function approve(id:unknown){const response=await fetch(`/api/finance/budgets/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"APPROVE"})}),json=await response.json();if(!response.ok){setMessage(json.error);return;}setMessage("تم اعتماد الميزانية وأصبحت متاحة للمقارنة");await reload();}
  return <div className="grid gap-6 xl:grid-cols-[420px_1fr]"><form onSubmit={send} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">ميزانية حسابية حسب الأبعاد</h2><input name="name" required placeholder="اسم الميزانية" className={input}/><select name="fiscalYearId" required value={yearId} onChange={e=>setYearId(e.target.value)} className={input}><option value="">السنة المالية</option>{data.fiscalYears.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select><select value={periodType} onChange={e=>setPeriodType(e.target.value)} className={input}><option value="ANNUAL">سنوية</option><option value="MONTHLY">شهرية</option></select>{periodType==="MONTHLY"&&<select name="fiscalPeriodId" required className={input}><option value="">الشهر/الفترة</option>{periods.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select>}<select name="accountId" required className={input}><option value="">الحساب</option>{data.accounts.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.code)} — {String(row.nameAr)}</option>)}</select><select name="costCenterId" className={input}><option value="">كل مراكز التكلفة</option>{data.costCenters.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.nameAr)}</option>)}</select><select name="departmentId" className={input}><option value="">كل الأقسام</option>{data.departments.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.nameAr)}</option>)}</select><input name="projectCode" placeholder="رمز المشروع (اختياري)" className={input}/><input name="amount" type="number" min="0" step="0.01" required placeholder="المبلغ المخطط" className={input}/><textarea name="notes" placeholder="ملاحظات" className={input}/><button disabled={busy} className="w-full rounded-lg bg-indigo-600 py-2 text-white">إنشاء الميزانية</button></form><div className="rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">الميزانيات</h2><SimpleTable heads={["الرقم","الاسم","السنة","البنود","القيمة","الحالة","الإجراء"]} rows={data.budgets.map(row=>[row.budgetNumber,row.name,(row.fiscalYear as Row)?.name,Array.isArray(row.lines)?row.lines.length:0,money(Array.isArray(row.lines)?(row.lines as Row[]).reduce((sum,line)=>sum+Number(line.amount),0):0),row.status,row.status==="DRAFT"?<button key={String(row.id)} onClick={()=>approve(row.id)} className="rounded bg-emerald-600 px-2 py-1 text-white">اعتماد</button>:"—"])}/></div></div>;
}

function ReportResult({data}:{data:Row|Row[]}) {
  const root=Array.isArray(data)?data:data as Row;
  let rows:Row[]=Array.isArray(root)?root:(Array.isArray(root.rows)?root.rows as Row[]:Array.isArray(root.items)?root.items as Row[]:Array.isArray(root.lines)?root.lines as Row[]:[]);
  if(!rows.length&&!Array.isArray(root)){const statement=root as Row;rows=[...Object.values(statement).flatMap(value=>value&&typeof value==="object"&&!Array.isArray(value)?Object.values(value as Row).flatMap(child=>Array.isArray(child)?child:[]):[]) as Row[]];}
  if(!rows.length)return <pre dir="ltr" className="max-h-[600px] overflow-auto rounded-xl bg-slate-950 p-4 text-xs text-emerald-300">{JSON.stringify(data,null,2)}</pre>;
  const columns=[...new Set(rows.flatMap(row=>Object.keys(row)))].filter(key=>!['id','transactions','sourceUrl','drilldownUrl'].includes(key)).slice(0,10);
  return <div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-100"><tr>{columns.map(key=><th className="p-3 text-right" key={key}>{key}</th>)}<th>التفاصيل</th></tr></thead><tbody>{rows.map((row,index)=><tr className="border-b" key={String(row.id??index)}>{columns.map(key=><td className="p-3" key={key}>{typeof row[key]==="number"?Number(row[key]).toLocaleString("en-US",{maximumFractionDigits:2}):String(row[key]??"—")}</td>)}<td>{row.sourceUrl||row.drilldownUrl?<a className="text-blue-700 underline" href={String(row.sourceUrl??row.drilldownUrl)}>فتح المصدر</a>:Array.isArray(row.transactions)?<details><summary className="cursor-pointer text-blue-700">حركات الأستاذ ({row.transactions.length})</summary><pre dir="ltr" className="max-w-md overflow-auto text-xs">{JSON.stringify(row.transactions,null,2)}</pre></details>:"—"}</td></tr>)}</tbody></table></div>;
}
